changeSet.sql:
DO $$
DECLARE
    r RECORD;
BEGIN
    -- Supprimer l'ancienne contrainte d'unicite globale sur reference (ex: uk_rj4mr27ga20ughn6qq6ev2uh0)
    FOR r IN (
        SELECT c.conname, t.relname
        FROM pg_constraint c
        JOIN pg_class t ON c.conrelid = t.oid
        JOIN pg_attribute a ON a.attrelid = c.conrelid AND a.attnum = ANY(c.conkey)
        WHERE c.contype = 'u'
          AND t.relname = 'produits'
          AND a.attname = 'reference'
          AND array_length(c.conkey, 1) = 1
    ) LOOP
        EXECUTE 'ALTER TABLE ' || quote_ident(r.relname) || ' DROP CONSTRAINT IF EXISTS ' || quote_ident(r.conname);
    END LOOP;
END $$;

DO $$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'uk_produits_tenant_reference') THEN
        ALTER TABLE produits ADD CONSTRAINT uk_produits_tenant_reference UNIQUE (point_de_vente_id, reference);
    END IF;
END $$;
